#include <stdio.h>

enum Light { RED, YELLOW, GREEN };

int main() {
    enum Light current = GREEN;
    if (current == GREEN) {
        printf("Go\n");
    } else {
        printf("Stop or wait\n");
    }
    return 0;
}
